import Browserbase from "@browserbasehq/sdk";
import { chromium } from "playwright";
const client = new Browserbase();
export async function withBrowser<T>(run: (browser: any) => Promise<T>): Promise<T> {
  const session = await client.sessions.create({projectId:process.env.BROWSERBASE_PROJECT_ID});
  try {
    const browser = await chromium.connectOverCDP(session.connectUrl);
    try { return await run(browser); }
    finally { await browser.close(); }
  } finally { await client.sessions.update(session.id,{status:'REQUEST_RELEASE'}); }
}

