import Kernel from "@onkernel/sdk";
import { chromium } from "playwright-core";
export async function readTitle(url: string): Promise<string> {
  const kernel = new Kernel();
  const b = await kernel.browsers.create();
  try {
    const browser = await chromium.connectOverCDP(b.cdp_ws_url);
    try {
      const context = browser.contexts()[0];
      const page = context.pages()[0] ?? await context.newPage();
      await page.goto(url);
      return await page.title();
    } finally { await browser.close(); }
  } finally { await kernel.browsers.deleteByID(b.session_id); }
}
export async function runInBrowser(sessionId: string) {
  return new Kernel().browsers.playwright.execute(sessionId, {code: "return await page.title()"});
}

