import Steel from "steel-sdk";
import puppeteer from "puppeteer-core";
import type { Account } from "./account.js";
export async function report(account: Account, url: string): Promise<string> {
  const client = new Steel({steelAPIKey: process.env.STEEL_API_KEY});
  const session = await client.sessions.create({timeout: 90000, sessionContext: account.steelContext});
  let browser;
  try {
    browser = await puppeteer.connect({browserWSEndpoint:
      `wss://connect.steel.dev?apiKey=${process.env.STEEL_API_KEY}&sessionId=${session.id}`});
    const context = browser.defaultBrowserContext();
    const page = (await context.pages())[0] ?? await context.newPage();
    await page.goto(url);
    return await page.title();
  } finally {
    try { await browser?.disconnect(); }
    finally { await client.sessions.release(session.id); }
  }
}

